"""IaC generator — scaffold infrastructure-as-code from project analysis.

Supports generating:
- Terraform (.tf) — AWS/GCP/Azure
- CloudFormation (YAML) — AWS
- Docker Compose — container orchestration
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from loguru import logger


_TERRAFORM_TEMPLATE = """\
# Generated by SharanBot IaC Generator
terraform {{
  required_version = ">= 1.0"
  required_providers {{
    aws = {{
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }}
  }}
}}

provider "aws" {{
  region = var.region
}}

variable "region" {{
  default = "{region}"
}}

variable "project_name" {{
  default = "{project_name}"
}}

# --- Compute ---
{compute_block}

# --- Outputs ---
output "project_name" {{
  value = var.project_name
}}
"""

_DOCKER_COMPOSE_TEMPLATE = """\
# Generated by SharanBot IaC Generator
version: "3.9"

services:
  {service_name}:
    build:
      context: .
      dockerfile: Dockerfile
    ports:
      - "{port}:{port}"
    environment:
      - NODE_ENV=production
    restart: unless-stopped
    volumes:
      - .:/app
"""

_CLOUDFORMATION_TEMPLATE = """\
# Generated by SharanBot IaC Generator
AWSTemplateFormatVersion: "2010-09-09"
Description: "{project_name} infrastructure"

Parameters:
  Environment:
    Type: String
    Default: production
    AllowedValues: [production, staging, development]

Resources:
  AppBucket:
    Type: AWS::S3::Bucket
    Properties:
      BucketName: !Sub "${{AWS::StackName}}-app-${{Environment}}"

Outputs:
  BucketName:
    Value: !Ref AppBucket
"""


class IaCGenerator:
    """Generate infrastructure-as-code from project metadata.

    Usage:
        gen = IaCGenerator(project_name="my-app")
        gen.generate_terraform(Path("infra/"))
        gen.generate_docker_compose(Path("."))
    """

    def __init__(self, project_name: str = "sharanbot-app", region: str = "us-east-1"):
        self._project = project_name
        self._region = region

    def generate_terraform(
        self,
        output_dir: Path,
        *,
        compute_type: str = "ecs",
    ) -> Path:
        """Generate a Terraform configuration."""
        output_dir.mkdir(parents=True, exist_ok=True)
        filepath = output_dir / "main.tf"

        if compute_type == "ecs":
            compute = (
                'resource "aws_ecs_cluster" "main" {\n'
                '  name = "${var.project_name}-cluster"\n'
                "}"
            )
        elif compute_type == "lambda":
            compute = (
                'resource "aws_lambda_function" "main" {\n'
                '  function_name = "${var.project_name}-fn"\n'
                '  runtime       = "python3.11"\n'
                '  handler       = "main.handler"\n'
                '  filename      = "lambda.zip"\n'
                "}"
            )
        else:
            supported = "ecs, lambda"
            logger.warning("Unsupported compute type '{}'; supported: {}", compute_type, supported)
            compute = (
                f"# Unsupported compute type: {compute_type}\n"
                f"# Supported types: {supported}\n"
                f"# Replace this block with the appropriate resource definition."
            )

        content = _TERRAFORM_TEMPLATE.format(
            region=self._region,
            project_name=self._project,
            compute_block=compute,
        )
        filepath.write_text(content, encoding="utf-8")
        logger.info("Generated Terraform config: {}", filepath)
        return filepath

    def generate_docker_compose(
        self,
        output_dir: Path,
        *,
        service_name: str | None = None,
        port: int = 8080,
    ) -> Path:
        """Generate a Docker Compose file."""
        output_dir.mkdir(parents=True, exist_ok=True)
        filepath = output_dir / "docker-compose.generated.yml"

        svc = service_name or self._project.replace(" ", "-").lower()
        content = _DOCKER_COMPOSE_TEMPLATE.format(
            service_name=svc,
            port=port,
        )
        filepath.write_text(content, encoding="utf-8")
        logger.info("Generated Docker Compose: {}", filepath)
        return filepath

    def generate_cloudformation(self, output_dir: Path) -> Path:
        """Generate a CloudFormation template."""
        output_dir.mkdir(parents=True, exist_ok=True)
        filepath = output_dir / "cloudformation.yaml"

        content = _CLOUDFORMATION_TEMPLATE.format(project_name=self._project)
        filepath.write_text(content, encoding="utf-8")
        logger.info("Generated CloudFormation: {}", filepath)
        return filepath

    def generate_all(self, output_dir: Path) -> list[Path]:
        """Generate all supported IaC files."""
        files = [
            self.generate_terraform(output_dir / "terraform"),
            self.generate_docker_compose(output_dir),
            self.generate_cloudformation(output_dir / "cloudformation"),
        ]
        return files
